"d:вперёд": "алдиға",
"Записываем числа в столбик: единицы под единицами, десятки под десятками. Начинаем с единиц.": "Санларни устун шәклидә йезимиз: бирликләр бирликләр астиға, оннлуқлар оннлуқлар астиға. Бирликләрдин башлаймиз.",
"У числа 100 нет ни десятков, ни единиц. Разменяем сотню: 100 = 9 десятков и 10 единиц.": "100 санида оннлуқ вә бирлик йоқ. Йүзни алмаштурайли: 100 = 9 оннлуқ вә 10 бирлик.",
"Это однозначное число: в нём только единицы.": "Бу бир ханилиқ сан: униңда пәқәт бирликләр бар.",
"100 — это 10 десятков. Перед ним 99. После него — 101.": "100 — бу 10 оннлуқ. Униң алдида 99. Кейинидә 101.",
"Хорошо! Числа идут по порядку: каждое следующее на 1 больше.": "Яхши! Санлар тәртип бойичә кетиду: һәр кейинкиси 1 гә чоң.",
"10 единиц — это 1 десяток! Собираем их в палочку.": "10 бирлик — бу 1 оннлуқ! Уларни таяқчиға жиғимиз.",
"Десяток разменяли на 10 единиц и одну убрали.": "Оннлуқни 10 бирликкә алмаштуруп, бирини елип ташлидуқ.",
"Все числа собраны! 🌟": "Барлиқ санлар жиғилди! 🌟",
"Нажми «+ сотня»": "«+ йүз» ни бес",
"10 сотен — это 1000, тысяча! Одна сотня — это 10 десятков, то есть 100.": "10 йүз — бу 1000, мың! Бир йүз — 10 оннлуқ, йәни 100.",
"Тысяча! Дальше считать сотнями не нужно.": "Мың! Йәнә йүзләп санаш керәк әмәс.",
"Выбери, как считать 👆": "Қандақ санашни таллаң 👆",
"по 3": "3 лап",
"по 4": "4 лап",
"по 5": "5 лап",
"Все три счёта посмотрели!": "Үч хил санашниң һәммисини көрдиң!",
"Один кружок остался без пары.": "Бир тәгрә жүпсиз қалди.",
"Все кружки встали в пары, лишнего нет.": "Барлиқ тәгриләр жүп-жүп болди, артуқи йоқ.",
"Замечаешь? Чётные числа оканчиваются на 0, 2, 4, 6, 8. Нечётные — на 1, 3, 5, 7, 9.": "Диққәт қилдиңму? Жүп санлар 0, 2, 4, 6, 8 билән түгәйду. Тақ санлар — 1, 3, 5, 7, 9 билән.",
"Нужно посмотреть несколько чётных и несколько нечётных чисел.": "Бир нәччә жүп вә бир нәччә тақ санға қараш керәк.",
"На сколько равных частей делим?": "Нәччә тәң қисимға бөлимиз?",
"Хорошо! Равные части — это когда в каждой одинаково.": "Яхши! Тәң қисимлар — һәр биридә охшаш болғанда.",
"Попробуй ещё несколько делений.": "Йәнә бир нәччә бөлүшни синап көр.",
"Алгоритм понятен! Теперь потренируемся сами.": "Алгоритм чүшинишлик! Һазир өзимиз машиқлинимиз.",
"Следующий шаг →": "Кейинки қәдәм →",
"групп": "топ",
"в каждой по": "һәр биридә",
"Это умножение:": "Бу көпәйтиш:",
"Видишь? Умножение — это сложение одинаковых слагаемых.": "Көрдиңму? Көпәйтиш — охшаш қошулғучиларни қошуш.",
"Это прямой угол": "Бу тик булуң",
"Это острый угол": "Бу ох булуң",
"Это тупой угол": "Бу дөң булуң",
"Прямой угол — как угол листа бумаги, угольника или квадрата.": "Тик булуң — қәғәз варақ, үчбулуңлуқ чизғуч яки квадрат булуңидәк.",
"Острый угол меньше прямого. Он острый, как кончик карандаша.": "Ох булуң тик булуңдин кичик. У қарандашниң учидәк өткүр.",
"Тупой угол больше прямого. Стороны «раскрылись» шире.": "Дөң булуң тик булуңдин чоң. Тәрәпләр кәңрәк «ечилған».",
"Все три вида углов найдены!": "Үч хил булуңниң һәммиси тепилди!",
"Начать заново": "Қайтидин башлаш",
"Все чертежи готовы! 🌟": "Барлиқ сизмилар тәйяр! 🌟",
"Не та точка. Пройди путь по шагам от красной точки, считая клетки.": "Бу нуқта әмәс. Қизил нуқтидин қәдәмму-қәдәм, катакларни санап йол мең.",
"Это не прямой угол. Стороны должны идти по клеточным линиям: одна вдоль, другая поперёк.": "Бу тик булуң әмәс. Тәрәпләр катак сизиқлири бойичә кетиши керәк: бири бойлап, иккинчиси кесип.",
"длина": "узунлуқ",
"клеток": "катак",
"Все фигуры построены! 🌟": "Барлиқ шәкилләр селинди! 🌟",
"У квадрата длина и ширина одинаковые.": "Квадратниң узунлуғи вә кәңлиги охшаш.",
"↻ четверть по часовой": "↻ саәт жебиси бойичә чоңқинчә",
"↺ четверть против часовой": "↺ саәт жебисигә қарши чоңқинчә",
"½ поворота": "½ айлиниш",
"Ты попробовал все повороты!": "Сән барлиқ бурулушларни синидиң!",
"Раздели прямоугольник на два квадрата (нажми на линию разреза)": "Тик төртбулуңни икки квадратқа бөл (кесиш сизиғини бес)",
"Раздели прямоугольник на два одинаковых прямоугольника (нажми на линию разреза)": "Тик төртбулуңни икки охшаш тик төртбулуңға бөл (кесиш сизиғини бес)",
