"Такой комплект уже есть. Ищи новый.": "Шундақ комплект бар. Йеңисини издә.",
"Есть!": "Бар!",
"Все комбинации найдены! 🌟": "Барлиқ комбинацияләр тепилди! 🌟",
"Опрос закончен! Вот таблица и диаграмма.": "Сориғучилиқ түгиди! Мана җәдвәл вә диаграмма.",
